import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto("http://localhost:3000/");
await page.evaluate(() => navigator.serviceWorker.ready);
// Poll until install-precache lands.
const summary = await page.evaluate(async () => {
  for (let i = 0; i < 50; i += 1) {
    const names = await caches.keys();
    const out: Record<string, string[]> = {};
    for (const name of names) {
      const cache = await caches.open(name);
      out[name] = (await cache.keys()).map((r) => new URL(r.url).pathname + new URL(r.url).search);
    }
    const assets = out["monecraft-assets-v1"] ?? [];
    const shell = out["monecraft-shell-v1"] ?? [];
    if (assets.length > 0 && shell.includes("/")) return out;
    await new Promise((r) => setTimeout(r, 200));
  }
  return null;
});
if (!summary) {
  console.log("PRECACHE NEVER COMPLETED");
} else {
  for (const [name, keys] of Object.entries(summary)) {
    console.log(`== ${name} (${keys.length})`);
    for (const k of keys.slice(0, 30)) console.log("   " + k);
  }
  const all = Object.values(summary).flat();
  console.log("api entries:", all.filter((k) => k.startsWith("/api/")).length);
}
// Now reload so the page is SW-controlled, go offline via CDP, reload again.
await page.reload();
const client = await page.context().newCDPSession(page);
await client.send("Network.enable");
await client.send("Network.emulateNetworkConditions", { offline: true, latency: 0, downloadThroughput: -1, uploadThroughput: -1 });
try {
  await page.reload({ timeout: 15000 });
  const gate = await page.getByText("Play locally").count();
  console.log("OFFLINE RELOAD OK, welcome gate visible:", gate > 0);
} catch (e) {
  console.log("OFFLINE RELOAD FAILED:", String(e).slice(0, 200));
}
await browser.close();

